CREATE TABLE social_accounts (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, network TEXT NOT NULL, remote_id TEXT NOT NULL, handle TEXT NOT NULL DEFAULT '', display_name TEXT NOT NULL DEFAULT '', instance TEXT, language TEXT NOT NULL DEFAULT 'en', status TEXT NOT NULL DEFAULT 'active', status_reason TEXT, token_ciphertext TEXT, token_expires_at INTEGER, refresh_lease_until INTEGER, connected_by TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE (channel_id, network, remote_id));
CREATE TABLE social_audit (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, target TEXT, detail TEXT, created_at INTEGER NOT NULL);
CREATE TABLE social_deliveries (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, account_id TEXT NOT NULL, network TEXT NOT NULL, event TEXT NOT NULL, entity_id TEXT NOT NULL, entity_title TEXT, format TEXT NOT NULL, include_link INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, remote_id TEXT, remote_url TEXT, cost_micros INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, sent_at INTEGER, UNIQUE (account_id, event, entity_id));
CREATE TABLE social_instance_apps (instance TEXT PRIMARY KEY, client_id TEXT NOT NULL, client_secret_ciphertext TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE social_pending (id TEXT PRIMARY KEY, kind TEXT NOT NULL, channel_id TEXT NOT NULL, user_id TEXT NOT NULL, network TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'en', data_ciphertext TEXT, expires_at INTEGER NOT NULL);
CREATE TABLE social_rules (account_id TEXT NOT NULL, event TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, format TEXT NOT NULL DEFAULT 'video', include_link INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY (account_id, event));
CREATE TABLE social_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_by TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE social_spend (month TEXT NOT NULL, network TEXT NOT NULL, cost_micros INTEGER NOT NULL DEFAULT 0, posts INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (month, network));
CREATE TABLE social_templates (channel_id TEXT NOT NULL, event TEXT NOT NULL, lang TEXT NOT NULL, body TEXT NOT NULL, updated_by TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY (channel_id, event, lang));
CREATE TABLE social_webhook_deliveries (id TEXT PRIMARY KEY, webhook_id TEXT NOT NULL, channel_id TEXT NOT NULL, event TEXT NOT NULL, entity_id TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, response_status INTEGER, last_error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE (webhook_id, event, entity_id));
CREATE TABLE social_webhooks (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, url TEXT NOT NULL, secret_ciphertext TEXT NOT NULL, events TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, failure_count INTEGER NOT NULL DEFAULT 0, last_status TEXT, last_delivery_at INTEGER, created_by TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE support_adjustments (id TEXT PRIMARY KEY, lines TEXT NOT NULL, reason TEXT NOT NULL, proposed_by TEXT NOT NULL, approvals TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'posted', 'rejected')), entry_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_bank_statements (id TEXT PRIMARY KEY, date TEXT NOT NULL, account TEXT NOT NULL CHECK (account IN ('creator_funds')), currency TEXT NOT NULL, balance INTEGER NOT NULL, entered_by TEXT NOT NULL, created_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_checkouts (id TEXT PRIMARY KEY, supporter_user_id TEXT NOT NULL, channel_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('one_time', 'monthly')), collector TEXT NOT NULL, mode TEXT NOT NULL, checkout_ref TEXT, gift INTEGER NOT NULL CHECK (gift > 0), charged INTEGER NOT NULL CHECK (charged > 0), currency TEXT NOT NULL, supporter_covers_fees INTEGER NOT NULL DEFAULT 0 CHECK (supporter_covers_fees IN (0, 1)), anonymous INTEGER NOT NULL DEFAULT 0 CHECK (anonymous IN (0, 1)), message TEXT, consent_text TEXT, consent_at TEXT, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'completed', 'expired')), created_at TEXT NOT NULL, completed_at TEXT) WITHOUT ROWID;
CREATE TABLE support_config (id TEXT PRIMARY KEY, policy TEXT NOT NULL DEFAULT '{}', collector TEXT NOT NULL DEFAULT 'test' CHECK (collector IN ('paygood', 'test')), mode TEXT NOT NULL DEFAULT 'test' CHECK (mode IN ('test', 'live')), collector_fees TEXT NOT NULL DEFAULT '{}', organisation_formed INTEGER NOT NULL DEFAULT 0 CHECK (organisation_formed IN (0, 1)), organisation_name TEXT, emergency_stop INTEGER NOT NULL DEFAULT 0 CHECK (emergency_stop IN (0, 1)), hold_all_payouts INTEGER NOT NULL DEFAULT 0 CHECK (hold_all_payouts IN (0, 1)), version INTEGER NOT NULL DEFAULT 0, updated_at TEXT, updated_by TEXT) WITHOUT ROWID;
CREATE TABLE support_country_rules (country TEXT PRIMARY KEY, supporters TEXT NOT NULL DEFAULT 'allowed' CHECK (supporters IN ('allowed', 'blocked')), creators TEXT NOT NULL DEFAULT 'allowed' CHECK (creators IN ('allowed', 'blocked', 'waitlist', 'external_link_only')), reason TEXT NOT NULL CHECK (reason IN ('sanctions', 'rail_unsupported', 'legal_review', 'admin')), changed_by TEXT NOT NULL, changed_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_disputes (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, collector_dispute_ref TEXT NOT NULL, reason TEXT, amount INTEGER NOT NULL, fee INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('open', 'evidence_sent', 'won', 'lost')), evidence_due_at TEXT, evidence_sent_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_events (id TEXT PRIMARY KEY, vendor TEXT NOT NULL, mode TEXT NOT NULL, event_id TEXT NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'processed', 'ignored', 'failed')), error TEXT, user_id TEXT, job_id TEXT, received_at TEXT NOT NULL, processed_at TEXT) WITHOUT ROWID;
CREATE TABLE support_finance_members (user_id TEXT PRIMARY KEY, roles TEXT NOT NULL DEFAULT '[]', added_by TEXT NOT NULL, approved_by TEXT, added_at TEXT NOT NULL, removed_at TEXT, removed_by TEXT) WITHOUT ROWID;
CREATE TABLE support_ledger (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, entry_id TEXT NOT NULL, entry_key TEXT NOT NULL, account TEXT NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('gift', 'collector_fee', 'settlement', 'release', 'refund', 'dispute', 'dispute_fee', 'dispute_reversal', 'payout', 'payout_paid', 'payout_fee', 'payout_return', 'rail_funding', 'fx', 'adjustment', 'write_off')), ref_table TEXT, ref_id TEXT, channel_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE support_ledger_entries (entry_key TEXT PRIMARY KEY, entry_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, channel_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_payees (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, owner_user_id TEXT NOT NULL, rail TEXT NOT NULL CHECK (rail IN ('wise', 'paypal-payouts', 'test')), mode TEXT NOT NULL CHECK (mode IN ('test', 'live')), rail_payee_ref TEXT, country TEXT, payout_currency TEXT, method TEXT, status TEXT NOT NULL DEFAULT 'not_started' CHECK (status IN ('not_started', 'pending', 'action_needed', 'active', 'restricted', 'disabled', 'closed')), tax_form TEXT NOT NULL DEFAULT 'none' CHECK (tax_form IN ('none', 'w9', 'w8ben', 'w8bene')), sanctions_status TEXT NOT NULL DEFAULT 'pending' CHECK (sanctions_status IN ('clear', 'pending', 'hold')), requirements TEXT NOT NULL DEFAULT '[]', payouts_held INTEGER NOT NULL DEFAULT 0 CHECK (payouts_held IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_from_event_at TEXT) WITHOUT ROWID;
CREATE TABLE support_payments (id TEXT PRIMARY KEY, pledge_id TEXT, checkout_id TEXT, supporter_user_id TEXT NOT NULL, channel_id TEXT NOT NULL, collector TEXT NOT NULL, mode TEXT NOT NULL, collector_payment_ref TEXT NOT NULL, gross INTEGER NOT NULL, currency TEXT NOT NULL, collector_fee INTEGER NOT NULL DEFAULT 0, tax INTEGER NOT NULL DEFAULT 0, refunded INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK (status IN ('succeeded', 'failed', 'refunded', 'partially_refunded', 'disputed', 'dispute_lost', 'dispute_won')), available_at TEXT, released_at TEXT, message TEXT, anonymous INTEGER NOT NULL DEFAULT 0 CHECK (anonymous IN (0, 1)), supporter_country TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_payout_batches (id TEXT PRIMARY KEY, period TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('draft', 'awaiting_approval', 'approved', 'funding', 'sending', 'done', 'stopped')), totals TEXT NOT NULL DEFAULT '{}', count INTEGER NOT NULL DEFAULT 0, prepared_by TEXT NOT NULL, approvals TEXT NOT NULL DEFAULT '[]', approved_at TEXT, funding_reference TEXT, stopped_reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_payouts (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL, payee_id TEXT NOT NULL, channel_id TEXT NOT NULL, rail TEXT NOT NULL, mode TEXT NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), currency TEXT NOT NULL, rail_fee INTEGER, fx_rate TEXT, rail_payout_ref TEXT, status TEXT NOT NULL CHECK (status IN ('queued', 'sent', 'unknown', 'paid', 'failed', 'returned', 'canceled')), failure_code TEXT, attempts INTEGER NOT NULL DEFAULT 0, sent_at TEXT, paid_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_pledges (id TEXT PRIMARY KEY, supporter_user_id TEXT NOT NULL, channel_id TEXT NOT NULL, collector TEXT NOT NULL, mode TEXT NOT NULL, collector_pledge_ref TEXT, amount INTEGER NOT NULL CHECK (amount > 0), currency TEXT NOT NULL, supporter_covers_fees INTEGER NOT NULL DEFAULT 0 CHECK (supporter_covers_fees IN (0, 1)), status TEXT NOT NULL CHECK (status IN ('active', 'past_due', 'canceled', 'ended')), anonymous INTEGER NOT NULL DEFAULT 0 CHECK (anonymous IN (0, 1)), started_at TEXT NOT NULL, current_period_end TEXT, canceled_at TEXT, cancel_reason TEXT, last_event_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_reconciliations (id TEXT PRIMARY KEY, date TEXT NOT NULL, currency TEXT NOT NULL, ledger_bank INTEGER NOT NULL, ledger_rail INTEGER NOT NULL, ledger_clearing INTEGER NOT NULL, collector_settled INTEGER, bank_balance INTEGER, rail_balance INTEGER, unbalanced_entries INTEGER NOT NULL DEFAULT 0, gap INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK (status IN ('ok', 'gap', 'incomplete')), resolved_by TEXT, resolved_at TEXT, created_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_refunds (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), currency TEXT NOT NULL, reason TEXT NOT NULL, requested_by TEXT NOT NULL CHECK (requested_by IN ('creator', 'admin', 'collector')), requested_by_user TEXT, status TEXT NOT NULL CHECK (status IN ('queued', 'pending', 'succeeded', 'failed')), collector_refund_ref TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_reports (id TEXT PRIMARY KEY, target_kind TEXT NOT NULL CHECK (target_kind IN ('channel', 'payment', 'pledge')), target_id TEXT NOT NULL, reporter_user_id TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'actioned', 'dismissed')), created_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_settings (channel_id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)), one_time_enabled INTEGER NOT NULL DEFAULT 1 CHECK (one_time_enabled IN (0, 1)), monthly_enabled INTEGER NOT NULL DEFAULT 1 CHECK (monthly_enabled IN (0, 1)), presets TEXT NOT NULL DEFAULT '[]', currency TEXT NOT NULL DEFAULT 'USD', thank_you_note TEXT, payout_threshold INTEGER, admin_paused INTEGER NOT NULL DEFAULT 0 CHECK (admin_paused IN (0, 1)), admin_paused_reason TEXT, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_tech_staff (user_id TEXT PRIMARY KEY, marked_by TEXT NOT NULL, marked_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE support_test_state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE tier_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tier_id TEXT NOT NULL, tier_name TEXT NOT NULL, from_tier_id TEXT NOT NULL, name TEXT NOT NULL, about TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'declined', 'withdrawn')), decline_reason TEXT, created_at TEXT NOT NULL, decided_at TEXT, decided_by TEXT, notified_at TEXT, email_status TEXT, email_error TEXT) WITHOUT ROWID;
CREATE TABLE translation_audit (id TEXT PRIMARY KEY, at TEXT NOT NULL, user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('inline', 'caption', 'viewer')), video_id TEXT, field TEXT, from_lang TEXT NOT NULL, to_lang TEXT NOT NULL, items INTEGER NOT NULL, chars INTEGER NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, cached INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE upload_limit_hits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, period TEXT NOT NULL, tier_id TEXT, hit_at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE upload_rate_leases (user_id TEXT NOT NULL, operation TEXT NOT NULL, lease_id TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY (user_id, operation, lease_id)) WITHOUT ROWID;
CREATE TABLE upload_rate_windows (user_id TEXT NOT NULL, operation TEXT NOT NULL, period TEXT NOT NULL, window_start INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY (user_id, operation, period)) WITHOUT ROWID;
CREATE TABLE video_categories (value TEXT PRIMARY KEY, label_en TEXT NOT NULL, label_ar TEXT NOT NULL, hint TEXT, position INTEGER NOT NULL, retired INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE videos_bans (user_id TEXT PRIMARY KEY, reason TEXT, banned_by TEXT NOT NULL, banned_at TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE yt_import_items (id TEXT PRIMARY KEY, import_id TEXT NOT NULL, channel_id TEXT NOT NULL, yt_video_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', title_localized TEXT, description_localized TEXT, tags TEXT, language TEXT, published_at TEXT, publish_at TEXT, duration_seconds INTEGER, yt_visibility TEXT NOT NULL, made_for_kids INTEGER NOT NULL DEFAULT 0, thumbnail_url TEXT, selected INTEGER NOT NULL DEFAULT 0, match_json TEXT, video_id TEXT, state TEXT NOT NULL DEFAULT 'available', thumbnail_state TEXT NOT NULL DEFAULT 'none', captions_state TEXT NOT NULL DEFAULT 'none', caption_languages TEXT, captions_attached TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, UNIQUE (import_id, yt_video_id));
CREATE TABLE yt_import_playlists (import_id TEXT NOT NULL, yt_playlist_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', yt_visibility TEXT NOT NULL, video_ids_json TEXT NOT NULL DEFAULT '[]', selected INTEGER NOT NULL DEFAULT 0, playlist_id TEXT, state TEXT NOT NULL DEFAULT 'none', PRIMARY KEY (import_id, yt_playlist_id));
CREATE TABLE yt_imports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, channel_id TEXT NOT NULL, owner_id TEXT NOT NULL, status TEXT NOT NULL, yt_channel_json TEXT, captions INTEGER NOT NULL DEFAULT 0, visibility_mode TEXT NOT NULL DEFAULT 'keep', refresh_token_enc TEXT, token_iv TEXT, scopes TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, finished_at TEXT, snapshot_purged_at TEXT);
